  "guide.setup.subtitle": "तपाईंले Perovo (तलब वा घरपरिवार) कसरी प्रयोग गर्नुहुन्छ समीक्षा गर्नुहोस् र आम्दानीका आधारभूत कुराहरू अपडेट गर्नुहोस्। तपाईंको बिलहरू तिनीहरू जस्तै रहन्छन्।",
