  "guide.household.inviteTitle": "तपाईंको परिवारको निमन्त्रणा कोड",
  "guide.household.inviteText": "यो ६-वर्णको कोड परिवारका सदस्यहरूसँग साझा गर्नुहोस्। तिनीहरू Perovo मा साइन इन गर्नुहोस्, Profile मा पारिवारिक मोड खोल्नुहोस्, र तपाईंको कोठामा सामेल हुन यो कोड प्रविष्ट गर्नुहोस्।",
  "guide.household.shareTitle": "तपाईंले साझेदारी गर्नुभएको कुरा नियन्त्रण गर्नुहोस्",
  "guide.household.shareText": "परिवारका सदस्यहरूले के देख्न सक्छन् भन्ने निर्णय गर्नुहोस्। अरूलाई तपाईंको दैनिक खर्च हेर्न दिनको लागि साझेदारी खर्च टगल गर्नुहोस्। तपाईंको प्रतिबद्धता सूची साझा गर्न बिल नामहरू टगल गर्नुहोस्।",
  "guide.household.outlookTitle": "घरपरिवारको दृष्टिकोण",
  "guide.household.outlookText": "तपाईंको परिवारको लागि संयुक्त वित्तीय स्वास्थ्य - आपतकालीन कोष कभरेज, साझा दबाब, र लक्ष्यहरू। कुनै पनि सदस्यको डाटा परिवर्तन हुँदा अद्यावधिकहरू।",
  "guide.pulse.label": "यो के हो?",
  "guide.pulse.pressureTitle": "दबाव स्कोर",
  "guide.pulse.pressureText": "तपाईंको वित्तीय दबाव स्कोर (0-100) मापन गर्दछ कि तपाईंको आय कति निश्चित दायित्वहरूमा जान्छ। 45 भन्दा कम स्वस्थ छ। 70 भन्दा माथिको मतलब तपाईंको दायित्वहरू भारी छन्।",
  "guide.pulse.freeCashTitle": "Free नगद",
  "guide.pulse.freeCashText": "यस महिना तपाईंको सबै प्रतिबद्ध भुक्तानीहरू पछि पैसा बाँकी छ। यो तपाईले वास्तवमा खर्च गर्न, बचत गर्न वा लगानी गर्नुपर्ने कुरा हो।",
  "guide.pulse.survivalTitle": "अस्तित्व रनवे",
