  "sync.freePlanBody": "Free योजनाले यो यन्त्रमा मात्र डाटा राख्छ। Pro वा Power मा अपग्रेड गर्नुहोस् तपाइँको खाता अन्तर्गत एक निजी Supabase ब्याकअप बचत गर्न (कुनै पनि समयमा सक्षम वा असक्षम गर्नुहोस्)।",
