  "profileHub.scoreWhy.health.good": "समग्र बानी र बफरहरू स्वस्थ देखिन्छन्।",
  "profileHub.scoreWhy.runway.what": "यदि आम्दानी रोकियो (तरल बचत + नि: शुल्क नगद) तपाईंले आवश्यक कुराहरू कभर गर्न सक्नुहुन्छ।",
  "profileHub.scoreWhy.runway.critical": "धेरै पातलो कुशन - एक आय झटका अवशोषित गर्न गाह्रो हुनेछ।",
