  "profileHub.scoreWhy.debt.high": "EMI भार भारी छ — नयाँ ऋणले नगद प्रवाहलाई तनाव दिनेछ।",
  "profileHub.scoreWhy.debt.ok": "ऋण भुक्तानी एक व्यवस्थित ब्यान्ड भित्र छन्।",
  "profileHub.scoreWhy.lending.what": "तपाईंले ऋणमा दिनुभएको वा प्राप्त गर्नुभएको समयमै भुक्तानीहरू ट्र्याक गर्दछ।",
